from django.test import TestCase, Client
from django.contrib.auth.models import User
from books.models import Organization, UserProfile, Sequence
import json


class OrganizationAndUserIdSecurityTests(TestCase):
    def setUp(self):
        self.client = Client()

    def test_organization_id_autogenerated_and_permanent(self):
        """Organization ID should be auto-generated in ORG-000001 format and remain permanent across saves."""
        org1 = Organization.objects.create(name="Alpha Org", code="ALPHA")
        self.assertIsNotNone(org1.organization_id)
        self.assertTrue(org1.organization_id.startswith("ORG-"))
        original_org_id = org1.organization_id

        # Update org and save again
        org1.name = "Alpha Org Updated"
        org1.save()
        org1.refresh_from_db()
        self.assertEqual(org1.organization_id, original_org_id)

        # Create second org
        org2 = Organization.objects.create(name="Beta Org", code="BETA")
        self.assertIsNotNone(org2.organization_id)
        self.assertTrue(org2.organization_id.startswith("ORG-"))
        self.assertNotEqual(org1.organization_id, org2.organization_id)

    def test_user_id_code_autogenerated_and_permanent(self):
        """User ID should be auto-generated in USR-00000001 format on profile creation and remain permanent."""
        user1 = User.objects.create_user(username="testuser1", email="test1@example.com", password="password123")
        profile1 = UserProfile.objects.create(user=user1, role="admin")
        self.assertIsNotNone(profile1.user_id_code)
        self.assertTrue(profile1.user_id_code.startswith("USR-"))
        original_user_id = profile1.user_id_code

        # Update profile and save again
        profile1.role = "manager"
        profile1.save()
        profile1.refresh_from_db()
        self.assertEqual(profile1.user_id_code, original_user_id)

        # Create second user
        user2 = User.objects.create_user(username="testuser2", email="test2@example.com", password="password123")
        profile2 = UserProfile.objects.create(user=user2, role="staff")
        self.assertIsNotNone(profile2.user_id_code)
        self.assertTrue(profile2.user_id_code.startswith("USR-"))
        self.assertNotEqual(profile1.user_id_code, profile2.user_id_code)

    def test_newly_registered_org_has_blank_optional_company_fields(self):
        """Newly created organizations must NOT inherit hardcoded dummy company info."""
        org = Organization.objects.create(name="Fresh Org", code="FRESH")
        self.assertEqual(org.company_id, "")
        self.assertEqual(org.gstin, "")
        self.assertEqual(org.phone, "")
        self.assertEqual(org.address, "")
        self.assertEqual(org.city, "")
        self.assertEqual(org.pincode, "")
        self.assertEqual(org.country, "")
        self.assertEqual(org.email, "")
        self.assertEqual(org.website, "")
        self.assertEqual(org.logo_data, "")

    def test_api_me_returns_user_id_and_org_id(self):
        """The /api/me/ endpoint should return the authenticated user's user_id and organization_id."""
        org = Organization.objects.create(name="My Company", code="MYCO")
        user = User.objects.create_user(username="john_doe", email="john@example.com", password="secretpassword")
        profile = UserProfile.objects.create(user=user, organization=org, role="admin")

        self.client.login(username="john_doe", password="secretpassword")
        response = self.client.get("/api/me/")
        self.assertEqual(response.status_code, 200)
        data = response.json()

        self.assertIn("user", data)
        self.assertEqual(data["user"]["user_id"], profile.user_id_code)
        self.assertEqual(data["user"]["username"], "john_doe")

        self.assertIn("organization", data)
        self.assertEqual(data["organization"]["organization_id"], org.organization_id)
        self.assertEqual(data["organization"]["name"], "My Company")

    def test_superuser_excluded_from_tenant_users_list(self):
        """Superusers must NOT appear in tenant user management APIs (/api/settings/users/)."""
        org = Organization.objects.create(name="Acme Corp", code="ACME")
        
        # Org admin user
        org_admin = User.objects.create_user(username="orgadmin", email="admin@acme.com", password="password123")
        UserProfile.objects.create(user=org_admin, organization=org, role="admin")

        # Regular tenant user
        tenant_staff = User.objects.create_user(username="tenantstaff", email="staff@acme.com", password="password123")
        UserProfile.objects.create(user=tenant_staff, organization=org, role="staff")

        # Platform Superuser
        superuser = User.objects.create_superuser(username="platform_root", email="root@convosis.com", password="supersecret")
        UserProfile.objects.create(user=superuser, organization=org, role="admin")

        self.client.login(username="orgadmin", password="password123")
        response = self.client.get("/api/settings/users/")
        self.assertEqual(response.status_code, 200)
        data = response.json()
        users_data = data.get("users", data)

        usernames = [u["username"] for u in users_data]
        self.assertIn("orgadmin", usernames)
        self.assertIn("tenantstaff", usernames)
        self.assertNotIn("platform_root", usernames)

        # Attempt to delete superuser via tenant endpoint must fail (404/not found in org scope)
        del_response = self.client.delete(f"/api/settings/users/{superuser.id}/")
        self.assertEqual(del_response.status_code, 404)

